"""Lazy iterable transformations usable as glom specs.

Each Iter method returns a new pipeline, leaving the original reusable.
Evaluation is lazy until a terminal operation such as all() or first().
"""
import itertools

from boltons.iterutils import chunked_iter, unique_iter
from .core import glom, T, SKIP, STOP, Path, TargetRegistry


_MISSING = object()


class First(object):
    """Return the first item for which *key* is truthy, or *default*."""
    def __init__(self, key=T, default=None):
        self.key = key
        self.default = default

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        for item in iterate(target):
            if scope[glom](item, self.key, scope):
                return item
        return self.default

    def __repr__(self):
        return 'First(%r, default=%r)' % (self.key, self.default)


class Iter(object):
    """Lazily apply *subspec* to each target item, then transform the stream."""
    def __init__(self, subspec=T, **kwargs):
        self.subspec = subspec
        self.sentinel = kwargs.pop('sentinel', STOP)
        if kwargs:
            raise TypeError('unexpected keyword arguments: %r' % sorted(kwargs))
        self._ops = ()

    def _add(self, name, *args):
        result = type(self)(self.subspec, sentinel=self.sentinel)
        result._ops = self._ops + ((name, args),)
        return result

    def map(self, subspec):
        return self._add('map', subspec)

    def filter(self, key=T):
        return self._add('filter', key)

    def chunked(self, size, fill=_MISSING):
        if size <= 0:
            raise ValueError('chunk size must be positive')
        return self._add('chunked', size, fill)

    def flatten(self):
        return self._add('flatten')

    def unique(self, key=T):
        return self._add('unique', key)

    def dropwhile(self, key=T):
        return self._add('dropwhile', key)

    def takewhile(self, key=T):
        return self._add('takewhile', key)

    def slice(self, *args):
        return self._add('slice', *args)

    def all(self):
        return (self, list)

    def first(self, key=T, default=None):
        return (self, First(key, default))

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        stream = self._map(iterate(target), self.subspec, scope)
        for name, args in self._ops:
            if name == 'map':
                stream = self._map(stream, args[0], scope)
            elif name in ('filter', 'dropwhile', 'takewhile', 'unique'):
                # Bind the spec in the callback: generators may outlive this
                # loop, and each stage must keep its own predicate.
                def key(item, spec=args[0]):
                    return scope[glom](item, spec, scope)
                if name == 'filter':
                    stream = filter(key, stream)
                elif name == 'unique':
                    stream = unique_iter(stream, key=key)
                else:
                    stream = getattr(itertools, name)(key, stream)
            elif name == 'chunked':
                size, fill = args
                stream = chunked_iter(stream, size, **({} if fill is _MISSING else {'fill': fill}))
            elif name == 'flatten':
                stream = itertools.chain.from_iterable(stream)
            elif name == 'slice':
                stream = itertools.islice(stream, *args)
        return stream

    def _map(self, stream, spec, scope):
        for i, item in enumerate(stream):
            value = scope[glom](item, spec, scope.new_child({Path: scope[Path] + [i]}))
            if value is self.sentinel or value is STOP:
                break
            if value is not SKIP:
                yield value

    def __repr__(self):
        result = 'Iter(%r)' % (self.subspec,)
        for name, args in self._ops:
            result += '.%s(%s)' % (name, ', '.join(repr(arg) for arg in args))
        return result
